<dialog id="product-{{ $item->id??'new' }}" class="editor-dialog"><div class="dialog-heading"><h2>{{ $item?'Edit product':'Add product' }}</h2><button data-close aria-label="Close product editor">×</button></div><form action="/admin/products{{ $item?'/'.$item->id:'' }}" method="post" enctype="multipart/form-data" class="dialog-content">@csrf<div class="form-grid">@foreach(['name'=>'Product name','sku'=>'SKU','category'=>'Category','weight'=>'Pack size','price'=>'Selling price (INR)','compare_price'=>'MRP (INR)','stock'=>'Available stock'] as $key=>$label)<label>{{ $label }}@if($key==='category')<select name="category" required><option value="">Select a category</option>@foreach($productCategories as $category)<option value="{{ $category->name }}" @selected(($item->category??'')===$category->name)>{{ $category->name }}</option>@endforeach</select>@else<input name="{{ $key }}" value="{{ in_array($key,['price','compare_price'])?(isset($item->$key)?number_format($item->$key/100,2,'.',''):''):($item->$key??'') }}" type="{{ in_array($key,['price','compare_price','stock'])?'number':'text' }}" @if(in_array($key,['price','compare_price'])) min="1" step="0.01" @elseif($key==='stock') min="0" step="1" @endif @required($key!=='compare_price') placeholder="{{ mz_placeholder($key,'partials/product-editor') }}"> @endif @if($key==='compare_price')<small>Optional. MRP must be equal to or above the selling price. A higher MRP automatically shows a Sale badge.</small>@endif</label>@endforeach @include('partials.pack-variant-editor') @foreach(['description'=>'Description','ingredients'=>'Ingredients','allergens'=>'Allergen information'] as $key=>$label)<label class="full">{{ $label }}<textarea name="{{ $key }}" rows="3" @required($key==='description') placeholder="{{ mz_placeholder($key,'partials/product-editor') }}">{{ $item->$key??'' }}</textarea></label>@endforeach<label>Main product image (1)<input type="file" name="image" accept="image/png,image/jpeg,image/webp"><small>JPG, PNG or WebP. Up to 2 MB.</small></label>@if($item&&($coverPhoto=mz_product_image($item)))<div class="full editor-main-photo"><img src="/{{ $coverPhoto }}" alt="{{ $item->name }} main image" width="90" height="110"><span class="small-copy">Current main image</span></div>@endif @php $savedGallery=$item?($productGalleries[$item->id]??collect()):collect(); @endphp<label class="full">Additional photos / infographics (up to 7)<input type="file" name="gallery_images[]" accept="image/jpeg,image/png,image/webp" multiple><small>{{ $savedGallery->count() }} of 7 extra images saved. Select multiple JPG, PNG or WebP files, up to 2 MB each. These appear as product-page thumbnails.</small></label>@if($savedGallery->isNotEmpty())<div class="full admin-gallery-preview">@foreach($savedGallery as $galleryImage)<a href="/admin/products/{{ $item->id }}/media" title="Manage this gallery"><img src="/{{ $galleryImage->path }}" alt="{{ $galleryImage->alt }}" loading="lazy" width="72" height="80"></a>@endforeach</div>@endif @if($item)<p class="full small-copy"><a href="/admin/products/{{ $item->id }}/media">Open Gallery to reorder/archive images or add videos and their thumbnails.</a></p>@endif<label class="checkbox full"><input type="checkbox" name="is_bestseller" value="1" @checked($item->is_bestseller??false)> Show in homepage bestsellers</label><details class="admin-extra full"><summary>Product suggestions and display settings</summary><div class="form-grid"><label>Homepage display order<input type="number" name="featured_rank" min="0" max="10000" value="{{ $item->featured_rank??0 }}" placeholder="{{ mz_placeholder('featured_rank','partials/product-editor') }}"><small>Lower numbers appear first.</small></label><label>Suggested products mode<select name="suggestion_mode"><option value="auto" @selected(($item->suggestion_mode??'auto')==='auto')>Automatic suggestions</option><option value="manual" @selected(($item->suggestion_mode??'auto')==='manual')>Choose products below</option><option value="hidden" @selected(($item->suggestion_mode??'auto')==='hidden')>Hide suggestions section</option></select></label><label>Number of suggestions to show<input type="number" name="related_display_limit" min="1" max="8" value="{{ $item->related_display_limit??4 }}" required placeholder="{{ mz_placeholder('related_display_limit','partials/product-editor') }}"></label><fieldset class="full suggested-product-options" data-suggestion-options><legend>Choose suggested products</legend><p class="small-copy">Tick to add a product, untick to remove it, then save. You can select up to 8 products. Selecting a checkbox switches to your chosen products.</p><div class="suggestion-checkbox-list">@foreach($products as $candidate)@if(!$item||$candidate->id!==$item->id)<label class="checkbox"><input type="checkbox" name="related_product_ids[]" value="{{ $candidate->id }}" @checked(in_array($candidate->id,json_decode($item->related_product_ids??'[]',true)?:[]))> {{ $candidate->name }}</label>@endif @endforeach</div></fieldset><div class="suggestion-save-row full"><span class="small-copy" data-selection-count>{{ count(json_decode($item->related_product_ids??'[]',true)?:[]) }} selected</span><button type="submit" class="button button-blue" aria-label="Save suggested products for {{ $item->name??'new product' }}">Save suggestions</button></div><label>Pack background colour<select name="colour">@foreach(['orange','blue','green','lilac'] as $colour)<option @selected(($item->colour??'orange')===$colour)>{{ $colour }}</option>@endforeach</select></label></div></details><label class="checkbox full"><input type="checkbox" name="active" value="1" @checked($item->active??true)> Published on website</label></div><button class="button button-blue">Save product</button></form>@if($item)<p class="dialog-archive"><a class="button button-outline" href="/admin/products/{{ $item->id }}/media">Manage photos and videos</a></p>@endif @if($item&&$item->active)<form action="/admin/archive/products/{{ $item->id }}" method="post" class="dialog-archive">@csrf<button class="text-link" data-confirm="Archive this product? It will be hidden from the store.">Archive product</button></form>@endif</dialog>
